This file is loaded as an ES module (a `<script type="module">` or a `.mjs` file in Node):

```js
console.log(this);
count = 1;
```

Which two statements are true? (Choose two.)

What does this log?

```js
let a = 0;
a ??= 5;
a ||= 7;
console.log(a);
```

What does this log?

```js
function* g() {
  yield 1;
  yield 2;
}
const it = g();
it.next();
it.next();
console.log(it.next());
```

What does this log?

```js
const m = '2026-10-06'.match(/(?<year>\d{4})-(?<month>\d{2})/);
console.log(m.groups.month);
```

Two files define and use a counter:

```js
// counter.mjs
export let count = 0;
export function inc() { count++; }

// main.mjs
import { count, inc } from './counter.mjs';
inc();
console.log(count);
```

A CommonJS version uses `module.exports = { count, inc }` and `const { count, inc } = require('./counter.cjs')`, where `inc` increments the local `count` variable inside counter.cjs. What do the two versions log?

What happens when app.mjs runs?

```js
// config.mjs
export let mode = 'dev';

// app.mjs
import { mode } from './config.mjs';
mode = 'prod';
```

What is the output order when you run `node main.mjs`?

```js
// main.mjs
console.log('main');
import './side.mjs';

// side.mjs
console.log('side');
```

Why does app.mjs fail, and what is the fix?

```js
// format.mjs
export default function format(n) { return n.toFixed(2); }

// app.mjs
const format = await import('./format.mjs');
console.log(format(3));
```

What does this log?

```js
function* g() {
  const x = yield 1;
  console.log(x);
}
const it = g();
it.next('a');
it.next('b');
```

What does this log?

```js
function* g() {
  yield 1;
  yield 2;
  return 3;
}
console.log([...g()]);
```

What does this log?

```js
const secret = Symbol('secret');
const user = { name: 'Ada', [secret]: 42 };
console.log(Object.keys(user).length, JSON.stringify(user), Reflect.ownKeys(user).length);
```

Put the console output in order when you run `node main.mjs`.

```js
// main.mjs
import './a.mjs';
import './b.mjs';
console.log('main');

// a.mjs
import './c.mjs';
console.log('a');

// b.mjs
import './c.mjs';
console.log('b');

// c.mjs
console.log('c');
```

What does this print? Type the two values separated by a space.

```js
const re = /a/g;
console.log(re.test('a'), re.test('a'));
```

These CommonJS files require each other. What does `node main.js` print?

```js
// a.js
exports.done = false;
const b = require('./b.js');
console.log('in a, b.done =', b.done);
exports.done = true;

// b.js
exports.done = false;
const a = require('./a.js');
console.log('in b, a.done =', a.done);
exports.done = true;

// main.js
require('./a.js');
```

You run `node a.mjs`. What happens?

```js
// a.mjs
import { b } from './b.mjs';
export const a = 'A';
console.log('a sees', b);

// b.mjs
import { a } from './a.mjs';
export const b = 'B';
console.log('b sees', a);
```

What does this log?

```js
const it = {
  i: 0,
  [Symbol.iterator]() { return this; },
  next() { return { value: this.i++, done: false }; },
  return() { console.log('cleanup'); return { done: true }; },
};
for (const x of it) { if (x === 2) break; }
const [p, q] = it;
console.log(p, q);
```

Put the logged values in order. Two of the `console.log` calls inside the generator never run.

```js
function* g() {
  console.log('1');
  try {
    yield;
    console.log('2');
  } finally {
    console.log('3');
  }
  console.log('4');
}
const it = g();
console.log('A');
it.next();
console.log('B');
it.return();
console.log('C');
```

What does this log?

```js
const target = {
  _name: 'target',
  get name() { return this._name; },
};
const proxy = new Proxy(target, {
  get(t, key, receiver) {
    if (key === '_name') return 'proxy';
    return t[key];
  },
});
console.log(proxy.name);
```

What does this do?

```js
class Account {
  #balance = 100;
  getBalance() { return this.#balance; }
}
const p = new Proxy(new Account(), {});
console.log(p.getBalance());
```

A package.json contains:

```json
{
  "name": "pkg",
  "exports": { ".": "./dist/index.js" }
}
```

An app calls `require('pkg/dist/utils.js')`, a file that does exist in the package. What happens in Node.js?

What does this log?

```js
const seen = new Set();
function tag(strings) { seen.add(strings); }
for (let i = 0; i < 3; i++) tag`item ${i}`;
tag`item ${0}`;
console.log(seen.size);
```

What does this log?

```js
function* g() {
  const a = yield 1;
  const b = yield a + 10;
  return a + b;
}
const it = g();
console.log(it.next(5).value, it.next(2).value, it.next(3).value);
```

What does this log?

```js
function* inner() {
  yield 'a';
  return 'r';
}
function* outer() {
  const v = yield* inner();
  yield v;
}
console.log([...outer()]);
```

What does this log?

```js
const target = {};
Object.defineProperty(target, 'version', { value: 1, writable: false, configurable: false });
const p = new Proxy(target, { get: () => 2 });
console.log(p.version);
```

You run `node a.mjs`. What is logged?

```js
// a.mjs
import { b } from './b.mjs';
export function a() { return 'A'; }
console.log(b());

// b.mjs
import { a } from './a.mjs';
export function b() { return 'B' + a(); }
console.log(a());
```

What does this log?

```js
function* g() {
  while (true) {
    try {
      yield 'ok';
    } catch (e) {
      console.log('caught', e);
    }
  }
}
const it = g();
it.next();
console.log(it.throw('boom').value);
```

What does this log?

```js
const re = /\d/g;
re.lastIndex = 2;
const found = [...'1a2b3'.matchAll(re)].map((m) => m[0]).join('');
console.log(found, re.lastIndex);
```

What does this log?

```js
const base = { hi() { return 'base'; } };
const obj = {
  __proto__: base,
  hi() { return 'obj>' + super.hi(); },
};
const other = {
  __proto__: { hi() { return 'other-proto'; } },
  hi: obj.hi,
};
console.log(other.hi());
```

How many times is `gen` logged? Type a number.

```js
function* naturals() {
  let n = 0;
  while (true) {
    console.log('gen', n);
    yield n++;
  }
}
function* take(iter, k) {
  for (const x of iter) {
    if (k-- <= 0) return;
    yield x;
  }
}
console.log([...take(naturals(), 2)]);
```
